sieve-machine-inbound-admin-only.contents:
require ["variables", "envelope", "reject"];

if allof(
    envelope :domain :is "to" "home.arpa",
    anyof(
        envelope :localpart :matches "to" "hv-*",
        envelope :localpart :matches "to" "ws-*"
    ),
    not string :is "${env.authenticated_as}" ["admin@home.arpa", "cluster-admin@home.arpa"]
) {
    reject "550 5.7.1 Machine mailbox accepts administrative senders only.";
}
